// Unicode subscript → ASCII digit (₂₃₄₅₆₇₈ etc).
// Also normalizes subscript x (\u2093) and subscript minus (\u208B) so Sialon's
// Si₆₋ₓAlₓOₓN₈₋ₓ formula maps to the 'Si6-xAlxOxN8-x' table key.
function _normalizeFormula(f) {
  if (!f) return f;
  return f
    .replace(/[\u2080-\u2089]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x2080 + 0x30))
    .replace(/\u2093/g, 'x')
    .replace(/\u208B/g, '-');
}

function _radiusFor(el, elementsMap) {
  return (elementsMap[el] && elementsMap[el].radius) || 0.8;
}

function generateAtomsFromPrototype(s, elementsMap) {
  const entry = PROTOTYPE_TABLE[_normalizeFormula(s.formula)];
  if (!entry) return null;
  const def = PROTOTYPE_DEFS[entry.proto];
  if (!def) return null;

  const { params, cation, anion, cations } = entry;
  const lat = def.lattice(params);
  const [Nx, Ny, Nz] = def.supercell;
  const cutoff = def.bondCutoff(params);
  const cutoff2 = cutoff * cutoff;

  // Multi-cation prototypes (rocksalt_mix) cycle a `cations[]` list over the
  // cation sites — a schematic for solid solutions like (Hf,Zr,Ti,Ta,Nb)C.
  let cationCount = 0;
  const cationFor = () => cations ? cations[cationCount++ % cations.length] : cation;

  // Tile basis across supercell.
  const atoms = [];
  for (let i = 0; i < Nx; i++) {
    for (let j = 0; j < Ny; j++) {
      for (let k = 0; k < Nz; k++) {
        for (const b of def.basis) {
          const u = b.fx + i, v = b.fy + j, w = b.fz + k;
          const x = u*lat[0][0] + v*lat[1][0] + w*lat[2][0];
          const y = u*lat[0][1] + v*lat[1][1] + w*lat[2][1];
          const z = u*lat[0][2] + v*lat[1][2] + w*lat[2][2];
          const el = (b.role === 'C') ? cationFor() : anion;
          atoms.push({ e: el, x, y, z, r: _radiusFor(el, elementsMap), cn: 0 });
        }
      }
    }
  }
  // Center at origin.
  let cx = 0, cy = 0, cz = 0;
  for (const a of atoms) { cx += a.x; cy += a.y; cz += a.z; }
  cx /= atoms.length; cy /= atoms.length; cz /= atoms.length;
  for (const a of atoms) { a.x -= cx; a.y -= cy; a.z -= cz; }

  // Build bonds via distance cutoff. Skip homoatomic pairs unless the
  // prototype explicitly opts in (e.g. AlB2 boron honeycomb).
  const bonds = [];
  const bondTypes = [];
  const cn = new Array(atoms.length).fill(0);
  const allowHomo = !!def.homoatomicBonds;
  for (let i = 0; i < atoms.length; i++) {
    for (let j = i+1; j < atoms.length; j++) {
      if (!allowHomo && atoms[i].e === atoms[j].e) continue;
      const dx = atoms[i].x - atoms[j].x;
      const dy = atoms[i].y - atoms[j].y;
      const dz = atoms[i].z - atoms[j].z;
      const d2 = dx*dx + dy*dy + dz*dz;
      if (d2 < cutoff2 && d2 > 1e-6) {
        bonds.push([i, j]);
        bondTypes.push([atoms[i].e, atoms[j].e].sort().join('-'));
        cn[i]++; cn[j]++;
      }
    }
  }
  for (let i = 0; i < atoms.length; i++) atoms[i].cn = cn[i];

  return {
    atoms, bonds, bondTypes,
    cellVectors: lat,
    supercell: def.supercell.slice(),
    prototype: entry.proto,
  };
}

function ensureElementsCoverage(elementsMap) {
  for (const [sym, meta] of Object.entries(FALLBACK_ELEMENT_META)) {
    if (!elementsMap[sym]) elementsMap[sym] = meta;
  }
}

