function ensureBondColorsCoverage(bondColorsMap) {
  if (!bondColorsMap || typeof bondColorsMap !== 'object') return;
  for (const [pair, c] of Object.entries(FALLBACK_BOND_COLORS)) {
    if (!bondColorsMap[pair]) bondColorsMap[pair] = c;
  }
}

function promoteStubsWithPrototypes(structures, elementsMap) {
  let promoted = 0;
  for (const s of structures) {
    if (!s.isStub) continue;
    const gen = generateAtomsFromPrototype(s, elementsMap);
    if (!gen) continue;
    s.atoms       = gen.atoms;
    s.bonds       = gen.bonds;
    s.bondTypes   = gen.bondTypes;
    s.cellVectors = gen.cellVectors;
    s.supercell   = gen.supercell;
    s.prototype   = gen.prototype;
    s.proceduralFallback = true;
    s.isStub      = false;
    if (!Array.isArray(s.info)) s.info = [];
    s.info.unshift('Procedural approximation · ' + gen.prototype + ' prototype · Phase 3 (Taichi) will replace with simulation-derived coordinates');
    promoted++;
  }
  return promoted;
}

